bool spsc_push(spsc_ring_t *rb, uint8_t byte) {
  unsigned head = atomic_load_explicit(&rb->head, memory_order_relaxed);
  unsigned tail = atomic_load_explicit(&rb->tail, memory_order_acquire);
  if (head - tail >= SPSC_RING_SIZE) return false;
  rb->buffer[head & SPSC_RING_MASK] = byte;
  atomic_store_explicit(&rb->head, head + 1, memory_order_release);
  return true;
}

